     1	'use strict';
     2	
     3	const { AppError, notFound } = require('../lib/errors');
     4	const { sendJson, sendText, readJson } = require('./respond');
     5	
     6	const STATUS_BY_CODE = {
     7	  invalid: 400,
     8	  unauthorized: 401,
     9	  forbidden: 403,
    10	  not_found: 404,
    11	  conflict: 409,
    12	};
    13	
    14	const BODY_METHODS = new Set(['POST', 'PUT', 'PATCH']);
    15	
    16	function matchPath(parts, segments) {
    17	  if (parts.length !== segments.length) return null;
    18	  const params = {};
    19	  for (let i = 0; i < parts.length; i += 1) {
    20	    if (parts[i].startsWith(':')) {
    21	      params[parts[i].slice(1)] = decodeURIComponent(segments[i]);
    22	    } else if (parts[i] !== segments[i]) {
    23	      return null;
    24	    }
    25	  }
    26	  return params;
    27	}
    28	
    29	function createRouter() {
    30	  const routes = [];
    31	
    32	  function add(method, pattern, handler) {
    33	    routes.push({ method, parts: pattern.split('/').filter(Boolean), handler });
    34	  }
    35	
    36	  async function dispatch(req, res) {
    37	    const url = new URL(req.url, 'http://localhost');
    38	    const segments = url.pathname.split('/').filter(Boolean);
    39	    let pathMatched = false;
    40	    for (const route of routes) {
    41	      const params = matchPath(route.parts, segments);
    42	      if (!params) continue;
    43	      pathMatched = true;
    44	      if (route.method !== req.method) continue;
    45	      const body = BODY_METHODS.has(req.method) ? await readJson(req) : {};
    46	      const query = Object.fromEntries(url.searchParams);
    47	      const result = await route.handler({ req, params, query, body });
    48	      if (result.text !== undefined) return sendText(res, result.status, result.text, result.contentType);
    49	      return sendJson(res, result.status, result.body);
    50	    }
    51	    if (pathMatched) return sendJson(res, 405, { error: 'method not allowed' });
    52	    throw notFound('route not found');
    53	  }
    54	
    55	  async function handle(req, res) {
    56	    try {
    57	      await dispatch(req, res);
    58	    } catch (error) {
    59	      if (error instanceof URIError) return sendJson(res, 400, { error: 'malformed path' });
    60	      if (error instanceof AppError) return sendJson(res, STATUS_BY_CODE[error.code] || 400, { error: error.message });
    61	      return sendJson(res, 500, { error: 'internal error' });
    62	    }
    63	  }
    64	
    65	  return { add, handle };
    66	}
    67	
    68	module.exports = { createRouter };
