     1	'use strict';
     2	
     3	const { invalid } = require('../lib/errors');
     4	
     5	const MAX_BODY_BYTES = 1024 * 1024;
     6	
     7	function sendJson(res, status, body) {
     8	  const payload = body === undefined ? '' : JSON.stringify(body);
     9	  res.writeHead(status, {
    10	    'content-type': 'application/json; charset=utf-8',
    11	    'content-length': Buffer.byteLength(payload),
    12	  });
    13	  res.end(payload);
    14	}
    15	
    16	function sendText(res, status, text, contentType = 'text/plain; charset=utf-8') {
    17	  res.writeHead(status, { 'content-type': contentType, 'content-length': Buffer.byteLength(text) });
    18	  res.end(text);
    19	}
    20	
    21	function readJson(req) {
    22	  return new Promise((resolve, reject) => {
    23	    const chunks = [];
    24	    let size = 0;
    25	    req.on('data', (chunk) => {
    26	      size += chunk.length;
    27	      if (size <= MAX_BODY_BYTES) chunks.push(chunk);
    28	    });
    29	    req.on('end', () => {
    30	      if (size > MAX_BODY_BYTES) return reject(invalid('request body too large'));
    31	      if (size === 0) return resolve({});
    32	      let value;
    33	      try {
    34	        value = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    35	      } catch {
    36	        return reject(invalid('request body must be valid JSON'));
    37	      }
    38	      if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    39	        return reject(invalid('request body must be a JSON object'));
    40	      }
    41	      return resolve(value);
    42	    });
    43	    req.on('error', reject);
    44	  });
    45	}
    46	
    47	function parseCookies(header = '') {
    48	  const cookies = {};
    49	  for (const part of header.split(';')) {
    50	    const index = part.indexOf('=');
    51	    if (index < 1) continue;
    52	    cookies[part.slice(0, index).trim()] = decodeURIComponent(part.slice(index + 1).trim());
    53	  }
    54	  return cookies;
    55	}
    56	
    57	module.exports = { sendJson, sendText, readJson, parseCookies };
