     3	const DEFAULT_PAGE_SIZE = 20;
     4	const MAX_PAGE_SIZE = 100;
     5	
     6	function toPositiveInt(value, fallback) {
     7	  const number = Number.parseInt(value, 10);
     8	  return Number.isInteger(number) && number > 0 ? number : fallback;
     9	}
