    11	function paginate(items, query = {}) {
    12	  const pageSize = Math.min(toPositiveInt(query.pageSize, DEFAULT_PAGE_SIZE), MAX_PAGE_SIZE);
    13	  const page = toPositiveInt(query.page, 1);
