===== src/auth/tokens.js =====
     1	'use strict';
     2	
     3	const crypto = require('node:crypto');
     4	
     5	function createTokenService({ secret, ttlSeconds }) {
     6	  if (!secret) throw new Error('a token secret is required');
     7	
     8	  function sign(payload) {
     9	    return crypto.createHmac('sha256', secret).update(payload).digest('base64url');
    10	  }
    11	
    12	  function issue(claims) {
    13	    const exp = Math.floor(Date.now() / 1000) + ttlSeconds;
    14	    const payload = Buffer.from(JSON.stringify({ ...claims, exp })).toString('base64url');
    15	    return `${payload}.${sign(payload)}`;
    16	  }
    17	
    18	  function verify(token) {
    19	    const [payload, signature, extra] = String(token).split('.');
    20	    if (!payload || !signature || extra !== undefined) return null;
    21	    if (signature !== sign(payload)) return null;
    22	    let claims;
    23	    try {
    24	      claims = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));
    25	    } catch {
    26	      return null;
    27	    }
    28	    if (!claims || typeof claims.exp !== 'number' || claims.exp * 1000 <= Date.now()) return null;
    29	    return claims;
    30	  }
    31	
    32	  return { issue, verify };
    33	}
    34	
    35	module.exports = { createTokenService };
