     1	'use strict';
     2	
     3	const { unauthorized, forbidden } = require('../lib/errors');
     4	
     5	function createGuard({ tokens, users }) {
     6	  function authenticate(req) {
     7	    const [scheme, token] = (req.headers.authorization || '').split(' ');
     8	    if (scheme !== 'Bearer' || !token) return null;
     9	    const claims = tokens.verify(token);
    10	    return claims ? users.find(claims.sub) : null;
    11	  }
    12	
    13	  function requireUser(handler) {
    14	    return async (ctx) => {
    15	      const user = authenticate(ctx.req);
    16	      if (!user) throw unauthorized();
    17	      return handler({ ...ctx, user });
    18	    };
    19	  }
    20	
    21	  function requireAdmin(handler) {
    22	    return requireUser(async (ctx) => {
    23	      if (ctx.user.role !== 'admin') throw forbidden('admin role required');
    24	      return handler(ctx);
    25	    });
    26	  }
    27	
    28	  return { requireUser, requireAdmin };
    29	}
    30	
    31	module.exports = { createGuard };
