     1	'use strict';
     2	
     3	const crypto = require('node:crypto');
     4	
     5	function createStore() {
     6	  const collections = new Map();
     7	
     8	  function collection(name) {
     9	    if (!collections.has(name)) collections.set(name, new Map());
    10	    return collections.get(name);
    11	  }
    12	
    13	  return {
    14	    insert(name, doc) {
    15	      const record = { ...doc, id: crypto.randomUUID() };
    16	      collection(name).set(record.id, record);
    17	      return structuredClone(record);
    18	    },
    19	    get(name, id) {
    20	      const record = collection(name).get(id);
    21	      return record ? structuredClone(record) : null;
    22	    },
    23	    update(name, id, patch) {
    24	      const record = collection(name).get(id);
    25	      if (!record) return null;
    26	      Object.assign(record, patch);
    27	      return structuredClone(record);
    28	    },
    29	    list(name, predicate = () => true) {
