     6	
     7	const TRANSITIONS = {
     8	  pending: ['paid', 'cancelled'],
     9	  paid: ['shipped', 'cancelled'],
    10	  shipped: ['delivered', 'cancelled'],
    11	  delivered: [],
    12	  cancelled: [],
