    14	
    15	function normalizeItems(items) {
    16	  if (!Array.isArray(items) || items.length === 0) throw invalid('an order needs at least one item');
    17	  return items.map((item) => {
    18	    if (!item || typeof item.sku !== 'string' || item.sku.trim() === '') throw invalid('every item needs a sku');
    19	    if (!isAmount(item.unitPrice)) throw invalid('unitPrice must be a positive amount with at most two decimals');
    20	    if (!Number.isInteger(item.quantity) || item.quantity < 1) throw invalid('quantity must be a positive integer');
    21	    return { sku: item.sku.trim(), unitPrice: item.unitPrice, quantity: item.quantity };
    22	  });
    23	}
    24	
    25	function createOrderService({ store }) {
    26	  function create(user, { items }) {
    27	    const lines = normalizeItems(items);
    28	    return store.insert('orders', {
    29	      userId: user.id,
    30	      items: lines,
    31	      total: sumLines(lines),
    32	      status: 'pending',
    33	      createdAt: new Date().toISOString(),
    34	    });
    35	  }
    36	
    37	  function get(id) {
    38	    const order = store.get('orders', id);
    39	    if (!order) throw notFound('order not found');
    40	    return order;
    41	  }
    42	
    43	  function getOwned(user, id) {
    44	    const order = get(id);
    45	    if (user.role !== 'admin' && order.userId !== user.id) throw notFound('order not found');
    46	    return order;
    47	  }
    48	
    49	  function list(user, query) {
    50	    const visible = store.list('orders', (order) => user.role === 'admin' || order.userId === user.id);
    51	    return paginate(visible, query);
    52	  }
    53	
    54	  function all() {
    55	    return store.list('orders');
    56	  }
    57	
    58	  function transition(order, next, patch = {}) {
    59	    if (!TRANSITIONS[order.status].includes(next)) {
    60	      throw conflict(`order cannot move from ${order.status} to ${next}`);
    61	    }
    62	    return store.update('orders', order.id, { ...patch, status: next, updatedAt: new Date().toISOString() });
    63	  }
    64	
    65	  return {
    66	    create,
    67	    get,
    68	    getOwned,
    69	    list,
    70	    all,
    71	    cancel: (user, id) => transition(getOwned(user, id), 'cancelled'),
    72	    ship: (id) => transition(get(id), 'shipped'),
    73	    deliver: (id) => transition(get(id), 'delivered'),
    74	    markPaid: (id, paymentId) => transition(get(id), 'paid', { paymentId }),
    75	  };
    76	}
    77	
    78	module.exports = { createOrderService };
