    21	  function call(method, urlPath, { body, token } = {}) {
    22	    return new Promise((resolve, reject) => {
    23	      const payload = body === undefined ? undefined : JSON.stringify(body);
    24	      const headers = {};
    25	      if (payload !== undefined) headers['content-type'] = 'application/json';
    26	      if (token) headers.authorization = `Bearer ${token}`;
    27	      const req = http.request({ host: '127.0.0.1', port, method, path: urlPath, headers, agent: false }, (res) => {
    28	        const chunks = [];
