cat > /tmp/repro/http.js <<'EOF'
const path = require('node:path');
const ROOT = '<run-project>';
const fs = require('node:fs'); const os = require('node:os'); const http = require('node:http');
const { createApp } = require(ROOT + '/src/app.js');
const ADMIN = { email:'admin@example.com', password:'admin-password', name:'Admin' };
const PASSWORD='correct-horse';
(async () => {
  const reportDir = fs.mkdtempSync(path.join(os.tmpdir(),'repro-'));
  const app = createApp({ secret:'test-secret', reportDir, admin: ADMIN });
  const port = await app.listen(0);
  const call=(method,urlPath,{body,token}={})=>new Promise((res,rej)=>{
    const payload = body===undefined?undefined:JSON.stringify(body);
    const headers={}; if(payload!==undefined)headers['content-type']='application/json';
    if(token)headers.authorization=`Bearer ${token}`;
    const r=http.request({host:'127.0.0.1',port,method,path:urlPath,headers,agent:false},(x)=>{
      const c=[];x.on('data',d=>c.push(d));x.on('end',()=>{const t=Buffer.concat(c).toString('utf8');
      res({status:x.statusCode,body:(x.headers['content-type']||'').startsWith('application/json')&&t?JSON.parse(t):undefined,text:t});});});
    r.on('error',rej); r.end(payload);});
  const login=async(e,p=PASSWORD)=>(await call('POST','/sessions',{body:{email:e,password:p}})).body.token;
  const signUp=async(e)=>{await call('POST','/users',{body:{email:e,password:PASSWORD,name:'C'}});return login(e);};
  const adminToken = await login(ADMIN.email, ADMIN.password);
  const alice = await signUp('alice@example.com');
  const bob = await signUp('bob@example.com');

  const order = (await call('POST','/orders',{token:alice,body:{items:[{sku:'LAMP',unitPrice:24.5,quantity:2}]}})).body;
  const idor = await call('GET',`/orders/${order.id}`,{token:bob});
  console.log('D. IDOR: bob GET alice order ->', idor.status, JSON.stringify(idor.body), '(expected 404)');

  await call('POST','/payments',{token:alice,body:{orderId:order.id,amount:49}});
  await call('POST',`/orders/${order.id}/ship`,{token:adminToken});
  const can = await call('POST',`/orders/${order.id}/cancel`,{token:alice});
  console.log('E. cancel a SHIPPED order ->', can.status, can.body && can.body.status, '(expected 409)');

  fs.writeFileSync(path.join(reportDir,'..','traversal-secret.txt'),'TOP-SECRET');
  const trav = await call('GET','/reports/..%2Ftraversal-secret.txt',{token:adminToken});
  console.log('F. traversal GET /reports/..%2Ftraversal-secret.txt ->', trav.status, JSON.stringify(trav.text), '(expected 404)');

  const o2 = (await call('POST','/orders',{token:alice,body:{items:[{sku:'A',unitPrice:0.07,quantity:3},{sku:'B',unitPrice:0.1,quantity:1}]}})).body;
