 7	function createPaymentService({ store, orders, provider = 'manual' }) {
 8	  const gateway = getProvider(provider);
 9	
10	  function capture(user, { orderId, amount }) {
11	    if (typeof orderId !== 'string' || orderId === '') throw invalid('orderId is required');
12	    if (!isAmount(amount)) throw invalid('amount must be a positive amount with at most two decimals');
13	    const order = orders.getOwned(user, orderId);
14	    if (order.status !== 'pending') throw conflict('order is not awaiting payment');
15	    if (toCents(amount) !== toCents(order.total)) throw invalid('amount does not match the order total');
16	    const charge = gateway.charge({ amount, reference: order.id });
17	    const payment = store.insert('payments', {
18	      orderId: order.id,
19	      userId: user.id,
20	      amount,
21	      status: charge.status,
22	      providerReference: charge.id,
23	      createdAt: new Date().toISOString(),
24	    });
25	    orders.markPaid(order.id, payment.id);
26	    return payment;
27	  }
28	
29	  function get(user, id) {
30	    const payment = store.get('payments', id);
31	    if (!payment || (user.role !== 'admin' && payment.userId !== user.id)) throw notFound('payment not found');
32	    return payment;
33	  }
34	
35	  return { capture, get };
36	}
37	
38	module.exports = { createPaymentService };

