'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { paginate } = require('../src/lib/pagination');

const items = (count) => Array.from({ length: count }, (_, index) => index);

test('totalPages counts every page needed to show all items', async () => {
  assert.equal(paginate(items(0), {}).totalPages, 1);
  assert.equal(paginate(items(20), {}).totalPages, 1);
  assert.equal(paginate(items(21), {}).totalPages, 2);
  assert.equal(paginate(items(25), {}).totalPages, 2);
  assert.equal(paginate(items(40), {}).totalPages, 2);
  assert.equal(paginate(items(41), {}).totalPages, 3);
  assert.equal(paginate(items(5), { pageSize: '2' }).totalPages, 3);
});

test('a later page returns its own slice', async () => {
  const page = paginate(items(25), { page: '2' });
  assert.deepEqual(page.items, [20, 21, 22, 23, 24]);
  assert.equal(page.page, 2);
  assert.equal(page.total, 25);
});

test('pageSize is clamped and bad input falls back', async () => {
  assert.equal(paginate(items(5), { pageSize: '1000' }).pageSize, 100);
  assert.equal(paginate(items(5), { pageSize: 'abc' }).pageSize, 20);
  assert.equal(paginate(items(5), { page: '0' }).page, 1);
});
