const files=[]; (function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);e.isDirectory()?walk(p):p.endsWith('.js')&&files.push(p);}})(ROOT);
const rel=f=>path.relative(ROOT,f).split(path.sep).join('/');
const REQ="require('";
function requiresOf(src){
  const out=[]; let i=0;
  while((i=src.indexOf(REQ,i))!==-1){
    const start=i+REQ.length; const end=src.indexOf("')",start);
    if(end===-1)break;
    const spec=src.slice(start,end);
    if(spec.charAt(0)==='.')out.push(spec);
    i=end;
  }
  return out;
}
const graph=new Map();
for(const f of files){
  const deps=requiresOf(fs.readFileSync(f,'utf8')).map(s=>{
    let t=path.resolve(path.dirname(f),s); if(!t.endsWith('.js'))t+='.js'; return rel(t);});
  graph.set(rel(f),deps);
}
const state=new Map(); const cycles=[];
const dfs=(n,stack)=>{
  if(state.get(n)==='done')return;
  if(state.get(n)==='open'){cycles.push(stack.slice(stack.indexOf(n)).join(' -> '));return;}
  state.set(n,'open'); for(const d of graph.get(n)||[])dfs(d,stack.concat(d)); state.set(n,'done');};
for(const n of graph.keys())dfs(n,[n]);
console.log('modules analysed:',graph.size);
console.log('edges:',[...graph.values()].reduce((a,b)=>a+b.length,0));
console.log('import cycles:',cycles.length?cycles:'NONE');
const memo=new Map();
const depth=(n,seen)=>{
  if(seen.has(n))return{len:0,p:[n]};
  if(memo.has(n))return memo.get(n);
  let best={len:0,p:[n]}; const s=new Set(seen); s.add(n);
  for(const x of graph.get(n)||[]){const r=depth(x,s); if(r.len+1>best.len)best={len:r.len+1,p:[n].concat(r.p)};}
  memo.set(n,best); return best;};
let d0={len:0,p:[]};
for(const n of graph.keys()){const r=depth(n,new Set()); if(r.len>d0.len)d0=r;}
console.log('max import-chain depth:',d0.len,'|',d0.p.join(' -> '));
const IDENT=new RegExp('[A-Za-z_$][A-Za-z0-9_$]*','g');
const tokens=s=>new Set(s.match(IDENT)||[]);
const testSrc=fs.readdirSync(TESTD).map(t=>fs.readFileSync(path.join(TESTD,t),'utf8')).join('&#10;');
console.log('--- exported names referenced nowhere outside their own file ---');
let found=0;
for(const f of files){
  const src=fs.readFileSync(f,'utf8');
  const i=src.indexOf('module.exports');
  if(i===-1)continue;
  const open=src.indexOf('{',i), close=src.indexOf('}',open);
  if(open===-1||close===-1)continue;
  const names=src.slice(open+1,close).split(',').map(s=>s.trim()).filter(Boolean);
  const others=tokens(files.filter(x=>x!==f).map(x=>fs.readFileSync(x,'utf8')).join(' ')+' '+testSrc);
  for(const n of names){ if(!others.has(n)){console.log('  UNUSED EXPORT:',rel(f),'->',n);found++;} }
}
if(!found)console.log('  none');
